      "إنت مش هارب من الناس. ممكن تكون محتاجهم جدا.",
      "إنت هارب من نوع معين من الكلام.",
      "ونفس الناس دول، لو قعدت مع واحد فيهم لوحده وفتحتوا كلام حقيقي، ممكن تقعد ساعتين وما ترهقش.",
      "فالمشكلة مش في العدد، ولا في الزحمة. المشكلة في السطح.",
      "واللي بيحركك مش إنك شايف نفسك أحسن.",
      "وأنا بقول الجملة دي بوضوح لسبب.",
      "فيه ناس اتقال لهم إنهم متكبرين. أو إنهم بيعقدوا الدنيا. أو إنهم مش بيعرفوا يعيشوا.",
      "وهما مش كده.",
      "فيهم حاجة عميقة، والكلام اللي حواليهم مش بيسع الحاجة دي، فبتفضل جوه.",
      "والوجع مش من الناس. الوجع من المسافة بين اللي جواك واللي مطلوب منك تبينه."
