      "وده بيبان في حاجة صغيرة: بيطلع شغل من إيدك فيه حتة ناقصة، فبتشوفها وتصلحها. وفي نفس اليوم بتشوف فيه حاجة حلوة وبتقف عندها كمان، ومش بتعدي عليها بسرعة.",
      "والعلامة التانية إن الكشاف بيتحرك وبيفضل.",
      "بتحاول تبص لناحية تانية، فبينتقل من غير تعب كبير، وبيفضل في المكان اللي وجهته له قد ما إنت عايز.",
      "والفرق مش إنك تقدر تحركه. الفرق قد إيه بيفضل بعيد لما تسيبه.",
      "والعلامة التالتة إن الإحساس بيوصلك في وقته.",
      "بتحس الأول، وبتفهم بعدين. مش بتفهم بدل ما تحس، ومش بتقيس قبل ما تشوف.",
      "فالتجربة بتوصلك وهي لسه سخنة، والفهم بيجي بعدها فيزيدها مش يبدلها.",
