      "عالمك الجواني أوسع بكتير من اللي بيوصلك منه.",
      "وحاجات كويسة بتعدي عليك كل يوم وما بتلمسكش. مش لأنها مش موجودة، لأنها بره الميزان.",
      "وليه دي أخطر صورة؟",
      "لأن الناس اللي بتحبك، واللي عايزة لك الخير، بتشجعك على الحالة دي وهي مش دريانة.",
      "فلو كنت مستني إشارة من بره تقول لك إن فيه حاجة مش مظبوطة، الإشارة دي مش هتيجي.",
