      "والاتنين بيوصلوك، مش واحد بس. وده الفرق كله.",
      "والعلامة التالتة إنك بقيت تشوف اللي راجع لك.",
      "يعني ما بقتش بس شايف احتياج الناس. بقيت شايف اهتمامهم بيك كمان.",
      "فلما حد يسيب لك مساحة، أو يسأل عنك، أو يستنى منك تتكلم، ده بقى بيوصلك.",
      "وده بيغير حاجة كبيرة: الإحساس بإنك لوحدك بيقل، مش لأن الناس اتغيرت، لأنك بقيت شايفهم وهما بيبصوا ناحيتك.",
