    "m2.a3.rooting": [
      "اللي بتقراه عن نفسك دلوقتي مش جديد. العلما اتكلموا فيه من قرون.",
      "جه في الحديث إن القلب شديد التقلب، وإن مثله زي ريشة في أرض خالية، الريح بتقلبها ظهر لبطن. وفي القرآن: ﴿وَنُقَلِّبُ أَفْئِدَتَهُمْ وَأَبْصَارَهُمْ﴾.",
      "والغزالي فرق بين قلبين. قلب بيتقلب بإرادة صاحبه، فبيحرك نظره حيث يشاء. وقلب بيتقلب بحركة مش ماسكها، فبينتقل من جهة لجهة من غير استقرار.",
      "وده بالظبط اللي طلع في إجاباتك. الحركة جواك أصيلة وليها معنى، والسؤال مش عليها، السؤال على معرفتك إنت واقف فين وإنت فيها."
    ],

    "m2.a3.distinguish": [
      "الفرز هنا مختلف عن البابين اللي فاتوا، ولازم أقول ليه.",
      "في البابين اللي فاتوا، الفرز كان بالسؤال: إيه اللي بيوصلك؟",
      "وهنا التلاتة بيوصلهم حاجات متشابهة. اللي بيفرق حاجة تانية خالص: إيه اللي بيحرك الكشاف.",
      "تلات إجابات:",
      "إنت ماشي عادي، والكشاف مستقر نسبيا. وفجأة بيتحرك. إيه اللي حركه؟",
      "الأولى: حد ممكن يشوفك. مكالمة، أو رسالة، أو حد دخل الأوضة، أو حتى مجرد فكرة إن حد ممكن يشوفك. وفي اللحظة دي حاجة صغيرة اتغيرت: وقفتك، أو نبرتك، أو اللي بتفكر فيه. ودي بتشاور على الأول.",
      "والتانية: سؤال اتولد في دماغك. وإيه لو؟ ومحدش قاله لك. إنت اللي ولدته، وإنت اللي بتحاول تجاوبه، وكل إجابة بتولد سؤال جديد. ودي بتشاور على التاني.",
      "والتالتة: مفيش حاجة. مفيش لحظة، ومفيش حدث، ومفيش سبب تقدر تسميه. إنت بس اكتشفت بعد ساعة، أو بعد يوم، إنك ما بقتش في المكان اللي كنت فيه. ودي بتشاور على التالت.",
      "اختبار عملي:",
      "فكر في يوم عادي عدى عليك الأسبوع ده. وفيه حاجة كنت ناوي تعملها الصبح وما عملتهاش.",
      "ما تفكرش ليه ما عملتهاش. فكر في حاجة واحدة بس: امتى بالظبط قررت إنك مش هتعملها؟",
      "لو لاقيت اللحظة، وعارف الحاجة اللي خلتك تغير رأيك، فده بيشاور على الأول أو التاني.",
      "ولو ما لقتش اللحظة أصلا، فده بيشاور على التالت. لأن ما كانش فيه قرار. كان فيه انزلاق.",
      "والفرق بين الأول والتاني بعد كده:",
      "الأول بينتقل مرة واحدة في اتجاه واحد وبيفضل هناك، وبيرجع لنفسه في الخلوة لحظات قصيرة.",
      "والتاني بينط رايح جاي في نفس اليوم، وممكن في نفس الجملة. أنا حاسس إن كذا، بس مش عارف، يمكن أسأل حد. جملة واحدة فيها الاتنين.",
      "واعتراض متوقع:",
      "هتقول: أنا ثابت. أنا مش بتنقل.",
      "وممكن. بس السؤال مش بتتنقل، السؤال بتفضل في مكان واحد قد إيه قبل ما تنفلت؟",
      "والفرق مش إنك تقدر تحرك كشافك. الفرق قد إيه بيفضل بعيد لما تسيبه."
    ],

    "m2.a3.giftCost": [
      "كل باب فيه مكسب وفيه تمن. والاتنين بييجوا مع بعض.",
      "المكسب:",
      "إنت بتشوف الحاجة من ناحيتين، واللي واقف في ناحية واحدة ما بيشوفهاش.",
      "يعني لما يحصل خلاف بين اتنين، إنت بتفهم الاتنين فعلا. مش بتجامل، وإنت مش قاعد في النص عشان تهرب. إنت شايف منطق كل واحد فيهم من جوه.",
      "وده بيخليك أقرب حد للناس المختلفة عن بعضها. لأن اللي في ناحية واحدة بيشوف اللي مخالفه غلطان، وإنت بتشوفه واقف في مكان له سبب.",
      "والحركة دي كمان بتخليك مش متجمد. الرأي عندك ممكن يتغير لما تشوف حاجة جديدة، وده مش ضعف. فيه ناس عمرها ما بتغير رأي حتى لو الدنيا اتقلبت قدامها.",
      "وإنت بتقدر تتحرك.",
      "والتمن:",
      "إن الحركة دي مش في إيدك.",
      "فمفيش جهة بتعيشها كاملة. وإنت في ناحية، بتقيسها بالناحية التانية. فالحاجة اللي في إيدك دايما بتتقاس على اللي مش موجود.",
      "والتمن التاني أتقل: إنك مش عارف موقعك.",
      "فبتتكشف أحيانا في جهة ما قصدتهاش. بتقول رأي مش رأيك، أو توافق على حاجة ما كنتش موافق عليها، وتكتشف بعدها بيوم.",
      "وأتعب حاجة إنك مش لاقي حد تلومه. لا حد ضغط عليك، ولا إنت قررت. الحركة حصلت لوحدها.",
      "والعلامة اللي بتفرق:",
      "لما حد يسألك فجأة عن رأيك من غير مقدمات، إيه اللي بيحصل في الثانية الأولى؟",
      "لو عرفت إجابتك، وعرفت كمان إنها رأيك إنت مش رأي المكان، فالحركة في إيدك.",
      "ولو دورت على الإجابة في وشوش اللي قاعدين، فالحركة هي اللي بتحركك.",
      "وفيه فرق مهم لازم يتقال: إنك تجاري المكان أحيانا مش مشكلة. الفرق إنك تكون عارف إنك اخترت."
    ],

